#!/usr/bin/env python
"""Footprint pack: label-free per-income features that compare the competition data with rows generated by GReaT replicas
(no competition labels). For each row's income v:
  n_k(v)  count over train + test                      n_r(v), n_r(v | Yes)  counts in the replica pool (rescaled to n_k)
  over-emission log1p(n_k) - log1p(n_r), also signed by the original data's label for v
  smoothed replica Yes share for v; original-data label mean and multiplicity of v; whether v is in the original data
  the replica Yes share and over-emission of v's income // 1000 bin (a smoother fallback)
Replica pool: every sample file given (default features/replica_samples/*.csv.gz, from sample_replica.py), concatenated
into features/replica_pool.parquet.
Writes features/footprint.npy (train rows then test rows, 10 columns) + features/footprint_names.json.
Usage: python footprint.py [SAMPLE_FILE ...]"""
import json
import sys
from pathlib import Path

import numpy as np
import pandas as pd

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parents[1]))
from common.data import TARGET, read_original, read_test, read_train  # noqa: E402

FEATURES = HERE / 'features'


def replica_pool(files):
    files = [Path(p) for p in files] or sorted((FEATURES / 'replica_samples').glob('*.csv.gz'))
    assert files, 'no replica samples: run sample_replica.py first'
    P = pd.concat([pd.read_csv(p) for p in files], ignore_index=True)
    print('pooled', P.shape, 'Yes rate', (P[TARGET] == 'Yes').mean())
    P.to_parquet(FEATURES / 'replica_pool.parquet')
    return P


def main():
    FEATURES.mkdir(parents=True, exist_ok=True)
    P = replica_pool(sys.argv[1:])
    tr, te, o = read_train(), read_test(), read_original()
    inc = pd.concat([tr.Annual_Income_USD, te.Annual_Income_USD], ignore_index=True).astype(float)
    nk = inc.map(inc.value_counts()).to_numpy(float)
    pr = P.Annual_Income_USD.astype(float)
    py = (P[TARGET] == 'Yes').astype(float)
    scale = len(inc) / len(P)
    cnt_r = pr.value_counts()
    cnt_r1 = pr[py == 1].value_counts()
    nr = inc.map(cnt_r).fillna(0).to_numpy(float) * scale
    nr1 = inc.map(cnt_r1).fillna(0).to_numpy(float) * scale
    oi = o.Annual_Income_USD.astype(float)
    oy = (o[TARGET] == 'Yes').astype(float)
    om = oy.groupby(oi).mean()
    oc = oi.value_counts()
    ybar = inc.map(om).to_numpy(float)
    omult = inc.map(oc).fillna(0).to_numpy(float)
    in_orig = ~np.isnan(ybar)
    ybar = np.where(in_orig, ybar, -1)
    base = py.mean()
    rshare = (nr1 + 5 * base * scale) / (nr + 5 * scale)                     # smoothed replica Yes share for v
    over = np.log1p(nk) - np.log1p(nr)                                       # over-emission vs the replicas
    over_y1 = np.where(in_orig, over * (2 * np.maximum(ybar, 0) - 1), 0)     # signed by the original label
    p3 = (inc // 1000).astype(int)
    pp3 = (pr // 1000).astype(int)
    g = py.groupby(pp3).agg(['sum', 'count'])
    rs3 = p3.map((g['sum'] + 20 * base) / (g['count'] + 20)).fillna(base).to_numpy(float)
    k3 = p3.map(p3.value_counts()).to_numpy(float)
    r3 = p3.map(pp3.value_counts()).fillna(0).to_numpy(float) * scale
    F = np.column_stack([np.log1p(nk), np.log1p(nr), over, over_y1, np.log(rshare / (1 - rshare)), ybar, omult, in_orig.astype(float),
                         np.log(rs3 / (1 - rs3)), np.log1p(k3) - np.log1p(r3)]).astype(np.float32)
    names = ['log_n_kaggle', 'log_n_replica', 'over_emission', 'over_emission_x_parent_sign', 'replica_logit_share', 'orig_parent_ybar',
             'orig_multiplicity', 'in_original', 'replica_logit_share_k3', 'over_emission_k3']
    assert np.isfinite(F).all()
    np.save(FEATURES / 'footprint.npy', F)
    (FEATURES / 'footprint_names.json').write_text(json.dumps(names))
    print(F.shape, dict(zip(names, np.round(F.std(0), 3))))


if __name__ == '__main__':
    main()
